import { useEffect, useRef } from "react";

export default function Sparkline({ positive, width = 80, height = 24 }: { positive?: boolean | null; width?: number; height?: number }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);

    const points: number[] = [];
    const segments = 20;
    for (let i = 0; i <= segments; i++) {
      points.push(Math.random() * 0.6 + 0.2);
    }
    // bias trend
    if (positive === true) {
      for (let i = 0; i < points.length; i++) points[i] += (i / segments) * 0.3;
    } else if (positive === false) {
      for (let i = 0; i < points.length; i++) points[i] -= (i / segments) * 0.3;
    }

    const color = positive === false ? "#F7525F" : positive === true ? "#22c55e" : "#9ca3af";

    ctx.clearRect(0, 0, width, height);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    points.forEach((y, i) => {
      const x = (i / segments) * width;
      const py = height - y * height;
      if (i === 0) ctx.moveTo(x, py);
      else ctx.lineTo(x, py);
    });
    ctx.stroke();

    // gradient fill
    const gradient = ctx.createLinearGradient(0, 0, 0, height);
    gradient.addColorStop(0, color + "20");
    gradient.addColorStop(1, color + "00");
    ctx.fillStyle = gradient;
    ctx.lineTo(width, height);
    ctx.lineTo(0, height);
    ctx.closePath();
    ctx.fill();
  }, [positive, width, height]);

  return <canvas ref={canvasRef} style={{ width, height }} className="sparkline" />;
}

