function CandlestickCanvas({ timeframe }: { timeframe: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const w = rect.width;
    const h = rect.height;
    canvas.width = w * dpr;
    canvas.height = h * dpr;
    ctx.scale(dpr, dpr);

    ctx.clearRect(0, 0, w, h);

    // Grid
    ctx.strokeStyle = "#2e2e4a";
    ctx.lineWidth = 0.5;
    for (let i = 0; i <= 10; i++) {
      const y = (h / 10) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    for (let i = 0; i <= 20; i++) {
      const x = (w / 20) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }

    // Generate candles based on timeframe seed
    const seed = timeframe.length;
    const candleCount = Math.floor(w / 14);
    const candleWidth = 10;
    const gap = 4;
    let price = 260;

    for (let i = 0; i < candleCount; i++) {
      const x = i * (candleWidth + gap) + gap;
      const change = (Math.sin(i * 0.3 + seed) * 3 + (Math.random() - 0.5) * 4);
      const open = price;
      const close = price + change;
      const high = Math.max(open, close) + Math.random() * 3;
      const low = Math.min(open, close) - Math.random() * 3;

      const yOpen = h - ((open - 220) / 80) * h;
      const yClose = h - ((close - 220) / 80) * h;
      const yHigh = h - ((high - 220) / 80) * h;
      const yLow = h - ((low - 220) / 80) * h;

      const isGreen = close >= open;
      ctx.fillStyle = isGreen ? "#22c55e" : "#F7525F";
      ctx.strokeStyle = isGreen ? "#22c55e" : "#F7525F";

      // Wick
      ctx.beginPath();
      ctx.moveTo(x + candleWidth / 2, yHigh);
      ctx.lineTo(x + candleWidth / 2, yLow);
      ctx.stroke();

      // Body
      const bodyTop = Math.min(yOpen, yClose);
      const bodyHeight = Math.max(1, Math.abs(yClose - yOpen));
      ctx.fillRect(x, bodyTop, candleWidth, bodyHeight);

      price = close;
    }
  }, [timeframe]);

  return <canvas ref={canvasRef} className="h-full w-full" />;
}

