function getPage() {
  const path = window.location.pathname;
  if (path.includes("chart")) return "chart";
  if (path.includes("ideas")) return "ideas";
  if (path.includes("markets")) return "markets";
  if (path.includes("brokers")) return "brokers";
  return "home";
}

async function render() {
  const page = getPage();
  const container = document.getElementById("app");
  if (!container) return;

  const root = createRoot(container);

  if (page === "chart") {
    const { default: Chart } = await import("./pages/Chart");
    root.render(
      <StrictMode>
        <Chart />
      </StrictMode>
    );
  } else if (page === "ideas") {
    const { default: Ideas } = await import("./pages/Ideas");
    root.render(
      <StrictMode>
        <Ideas />
      </StrictMode>
    );
  } else if (page === "markets") {
    const { default: Markets } = await import("./pages/Markets");
    root.render(
      <StrictMode>
        <Markets />
      </StrictMode>
    );
  } else if (page === "brokers") {
    const { default: Brokers } = await import("./pages/Brokers");
    root.render(
      <StrictMode>
        <Brokers />
      </StrictMode>
    );
  } else {
    const { default: Home } = await import("./pages/Home");
    root.render(
      <StrictMode>
        <Home />
      </StrictMode>
    );
  }
}

